function setContext (instance, context) {
  // Use the selected 404 context as the prototype instead of copying it: the
  // hooks of a not-found handler are populated in a 'preReady' callback that
  // may run after this one, and a copy would freeze them as they are now.
  const _404Context = Object.create(instance[kFourOhFourContext])
  _404Context.onSend = context.onSend
  context[kFourOhFourContext] = _404Context
}
